<section class="page-hero compact"><div class="container"><span class="eyebrow">Administrator</span><h1>User Management</h1><p>Add users, verify accounts and remove users as defined in the project use case.</p></div></section>
<section class="section container admin-grid"><div class="panel"><h2>Add User</h2><form method="post" action="<?= e(url('admin/user/add')) ?>"><?= csrf_field() ?><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="8" required></label><label>Role<select name="role"><option value="user">Registered User</option><option value="scout">Scout</option><option value="admin">Administrator</option></select></label><label class="check-row"><input type="checkbox" name="is_verified" value="1"> Mark account as verified</label><button class="btn btn-primary btn-block" type="submit">Add User</button></form></div>
<div class="panel wide"><h2>All Users</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Verification</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $row): ?><tr><td><?= e($row['name']) ?></td><td><?= e($row['email']) ?></td><td><span class="role-pill"><?= e(ucfirst($row['role_name'])) ?></span></td><td><?= (int)$row['is_verified']===1?'<span class="verified-pill">Verified</span>':'<span class="pending-pill">Unverified</span>' ?></td><td><?= e(date('d M Y',strtotime($row['created_at']))) ?></td><td><div class="table-actions"><?php if((int)$row['is_verified']!==1): ?><form method="post" action="<?= e(url('admin/user/verify')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="btn btn-soft btn-sm" type="submit">Verify</button></form><?php endif; ?><?php if((int)$row['id']!==(int)auth()['id']): ?><form method="post" action="<?= e(url('admin/user/delete')) ?>" onsubmit="return confirm('Delete this user?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="btn btn-danger btn-sm" type="submit">Delete</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div></div></section>
